/*
 * Ramayana Storybook (v4) - a storytelling Tableau data app.
 *
 * Every page fits the screen: illustration on the LEFT, story on the RIGHT, no page scrolling.
 * Pages (built from data):
 *   cover -> the Path of Rama (journey map) -> for each Kanda: opener + one page per key moment.
 * Real Kanda names (Devanagari + transliteration) head every Kanda page.
 *
 * Data: 6 embedded datasources queried live through the Extensions API, found by caption.
 * Static helpers: geo.js (land silhouette, generated by pipeline/build_map.py) and images.js
 * (which illustrations exist). Safe DOM only; no external origins.
 */
(function () {
  'use strict';

  var root = document.getElementById('app');
  var GEO = window.RAMAYANA_GEO;
  var IMAGES = window.RAMAYANA_IMAGES || {};

  var TABLES = {
    kandas: { ds: 'Kandas', cols: ['Kanda ID', 'Kanda', 'Kanda Order', 'Kanda Devanagari', 'English Gloss', 'Story Intro', 'Scope Note'] },
    events: { ds: 'Events', cols: ['Event ID', 'Event', 'Kanda ID', 'Narrative Order', 'Location ID', 'Summary', 'Key Moment', 'Narrative', 'Confidence Label', 'Chronology Note'] },
    characters: { ds: 'Characters', cols: ['Character ID', 'Character', 'Description', 'Faction', 'Role'] },
    locations: { ds: 'Locations', cols: ['Location ID', 'Location', 'Modern Association', 'Confidence Label', 'Map Latitude', 'Map Longitude'] },
    participation: { ds: 'Event Participation', cols: ['Participation ID', 'Event ID', 'Character ID', 'Participation Role'] },
    journey: { ds: 'Journey', cols: ['Journey Stop ID', 'Journey Order', 'Location ID', 'Kanda ID', 'Story Milestone'] }
  };
  var TINTS = ['#8a5a1c', '#7a3f1a', '#3f5a2c', '#2f5a52', '#7a4a12', '#6e1f17', '#4a2a4a'];
  var DEVA_DIGITS = '०१२३४५६७८९';
  var MAP_LABELS = { L001: 'right', L006: 'left', L007: 'right', L008: 'left', L010: 'left', L015: 'right', L017: 'right', L014: 'left' };

  var DB = null, pages = [], at = 0, activeStop = null, traced = null, timer = null, dataNote = '';

  // ------------------------------------------------------------- safe DOM
  function mk(ns, tag, props, kids) {
    var el = ns ? document.createElementNS(ns, tag) : document.createElement(tag);
    Object.keys(props || {}).forEach(function (k) {
      var v = props[k];
      if (v === null || v === undefined || v === false) { return; }
      if (k === 'text') { el.textContent = v; }
      else if (k.slice(0, 2) === 'on') { el.addEventListener(k.slice(2), v); }
      else { el.setAttribute(k === 'cls' ? 'class' : k, v); }
    });
    (function add(list) {
      list.forEach(function (kid) {
        if (kid === null || kid === undefined || kid === false) { return; }
        if (Array.isArray(kid)) { add(kid); return; }
        el.appendChild(typeof kid === 'object' ? kid : document.createTextNode(String(kid)));
      });
    })(kids);
    return el;
  }
  function h(tag, props) { return mk(null, tag, props, Array.prototype.slice.call(arguments, 2)); }
  function s(tag, props) { return mk('http://www.w3.org/2000/svg', tag, props, Array.prototype.slice.call(arguments, 2)); }

  function renderError(msg) {
    root.textContent = '';
    root.appendChild(h('div', { cls: 'error' }, h('h2', { text: 'The story could not be loaded' }), h('p', { text: msg })));
  }

  // ------------------------------------------------------------- load + model
  function norm(k) { return String(k).toLowerCase().replace(/[^a-z0-9]/g, ''); }
  function num(v) { var n = Number(v); return isNaN(n) ? 0 : n; }
  function has(v) { return v !== '' && v !== null && v !== undefined && !isNaN(Number(v)); }
  function extract(r) { return r && Array.isArray(r.data) ? r.data : []; }

  // Describe an Extensions API error as fully as possible ("internal-error: error" alone is useless).
  function describe(err) {
    if (!err) { return 'unknown error'; }
    var parts = [err.errorCode, err.message].filter(Boolean);
    try { var j = JSON.stringify(err); if (j && j !== '{}') { parts.push(j.slice(0, 300)); } } catch (e) { /* ignore */ }
    return parts.join(' | ') || String(err);
  }

  // On failure, re-run the query one field at a time to name the field(s) the server rejects.
  function isolate(ds, spec, avail, err) {
    var bad = [];
    return spec.cols.reduce(function (p, c) {
      return p.then(function () {
        return ds.queryAsync({ fields: [{ fieldCaption: avail[norm(c)] }] }).catch(function () { bad.push(c); });
      });
    }, Promise.resolve()).then(function () {
      throw new Error('Query on "' + spec.ds + '" failed: ' + describe(err) +
        (bad.length ? ' | failing field(s): ' + bad.join(', ') : ' | every field works on its own (the combined query fails)'));
    });
  }

  function queryTable(ds, spec) {
    var avail = {};
    return ds.readMetadataAsync().catch(function (err) {
      throw new Error('Reading metadata of "' + spec.ds + '" failed: ' + describe(err));
    }).then(function (meta) {
      extract(meta).forEach(function (f) { var c = f.fieldCaption || f.fieldName; avail[norm(c)] = c; });
      var missing = spec.cols.filter(function (c) { return !avail[norm(c)]; });
      if (missing.length) { throw new Error('"' + spec.ds + '" is missing: ' + missing.join(', ') + ' (has: ' + Object.keys(avail).map(function (k) { return avail[k]; }).join(', ') + ')'); }
      return ds.queryAsync({ fields: spec.cols.map(function (c) { return { fieldCaption: avail[norm(c)] }; }) })
        .catch(function (err) { return isolate(ds, spec, avail, err); });
    }).then(function (res) {
      return extract(res).map(function (row) {
        var o = {};
        Object.keys(row).forEach(function (k) {
          var v = row[k];
          if (v && typeof v === 'object' && 'value' in v) { v = v.value; }
          o[norm(k)] = v === null || v === undefined ? '' : v;
        });
        return o;
      });
    });
  }

  // Live source: ONE published data source ("Ramayana Story Data", project Ramayan) holding every
  // table, distinguished by [Record Type]. Numeric columns are measures in that source, so they are
  // queried as MIN() grouped by the unique [Record ID], which returns each row's own value.
  var SOURCE = 'Ramayana Story Data';
  var RECORD_TYPE = { kandas: 'Kanda', events: 'Event', characters: 'Character', locations: 'Location', participation: 'Participation', journey: 'Journey' };
  var MEASURES = { 'Kanda Order': 1, 'Narrative Order': 1, 'Journey Order': 1, 'Map Latitude': 1, 'Map Longitude': 1 };

  // Devanagari is stored as \uXXXX escapes (Tableau's CSV reader is not UTF-8 safe).
  function unescapeText(v) {
    return typeof v === 'string' && v.indexOf('\\u') >= 0
      ? v.replace(/\\u([0-9a-fA-F]{4})/g, function (_, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      : v;
  }

  function load() {
    return tableau.extensions.workbook.getAllDataSourcesAsync().then(function (list) {
      var ds = (list || []).filter(function (d) { return d.name === SOURCE; })[0];
      if (!ds) { throw new Error('Data source "' + SOURCE + '" not found in the workbook'); }
      var cols = ['Record Type', 'Record ID'];
      Object.keys(TABLES).forEach(function (k) {
        TABLES[k].cols.forEach(function (c) { if (cols.indexOf(c) < 0) { cols.push(c); } });
      });
      setStatus('Reading the story…');
      return ds.readMetadataAsync().catch(function (err) {
        throw new Error('Reading metadata of "' + SOURCE + '" failed: ' + describe(err));
      }).then(function (meta) {
        var avail = {};
        extract(meta).forEach(function (f) { var c = f.fieldCaption || f.fieldName; avail[norm(c)] = c; });
        var missing = cols.filter(function (c) { return !avail[norm(c)]; });
        if (missing.length) { throw new Error('"' + SOURCE + '" is missing: ' + missing.join(', ')); }
        var fields = cols.map(function (c) {
          return MEASURES[c] ? { fieldCaption: avail[norm(c)], function: 'MIN', fieldAlias: c } : { fieldCaption: avail[norm(c)] };
        });
        return ds.queryAsync({ fields: fields }).catch(function (err) {
          return isolate(ds, { ds: SOURCE, cols: cols.filter(function (c) { return !MEASURES[c]; }) }, avail, err);
        });
      }).then(function (res) {
        var raw = {};
        Object.keys(RECORD_TYPE).forEach(function (k) { raw[k] = []; });
        var byType = {};
        Object.keys(RECORD_TYPE).forEach(function (k) { byType[RECORD_TYPE[k]] = k; });
        extract(res).forEach(function (row) {
          var o = {};
          Object.keys(row).forEach(function (key) {
            var v = row[key];
            if (v && typeof v === 'object' && 'value' in v) { v = v.value; }
            o[norm(key).replace(/^min/, '')] = v === null || v === undefined ? '' : unescapeText(v);
          });
          var k = byType[o.recordtype];
          if (k) { raw[k].push(o); }
        });
        if (!raw.events.length || !raw.kandas.length) { throw new Error('"' + SOURCE + '" returned no story rows'); }
        return model(raw);
      });
    });
  }

  function model(raw) {
    var by = function (key) { return function (a, b) { return num(a[key]) - num(b[key]); }; };
    var idx = function (rows, key) { var m = {}; rows.forEach(function (r) { m[r[key]] = r; }); return m; };
    var db = { kandas: raw.kandas.sort(by('kandaorder')), events: raw.events.sort(by('narrativeorder')), journey: raw.journey.sort(by('journeyorder')) };
    db.c = idx(raw.characters, 'characterid');
    db.l = idx(raw.locations, 'locationid');
    db.cast = {};
    raw.participation.forEach(function (p) {
      (db.cast[p.eventid] = db.cast[p.eventid] || []).push({ c: db.c[p.characterid], primary: p.participationrole === 'Primary' });
    });
    Object.keys(db.cast).forEach(function (e) { db.cast[e].sort(function (a, b) { return (b.primary ? 1 : 0) - (a.primary ? 1 : 0); }); });
    db.firstIn = {};
    var seen = {};
    db.events.forEach(function (e) {
      (db.cast[e.eventid] || []).forEach(function (x) {
        if (x.c && !seen[x.c.characterid]) { seen[x.c.characterid] = 1; (db.firstIn[e.kandaid] = db.firstIn[e.kandaid] || []).push(x.c.character); }
      });
    });
    return db;
  }

  function buildPages() {
    pages = [{ type: 'cover' }, { type: 'path' }, { type: 'cast', part: 0 }, { type: 'cast', part: 1 }];
    DB.kandas.forEach(function (k, i) {
      var evs = DB.events.filter(function (e) { return e.kandaid === k.kandaid; });
      var keys = evs.filter(function (e) { return e.keymoment === 'Y'; });
      pages.push({ type: 'kanda', k: k, ki: i, evs: evs, keys: keys });
      keys.forEach(function (e, j) { pages.push({ type: 'moment', k: k, ki: i, e: e, n: j + 1, of: keys.length }); });
    });
    pages.push({ type: 'end' });
  }

  // Stable id per page, used to remember where the reader stopped.
  function pageId(p) { return p.type + (p.e ? ':' + p.e.eventid : p.k ? ':' + p.k.kandaid : p.type === 'cast' ? ':' + p.part : ''); }
  function pageLabel(p) {
    return p.type === 'moment' ? p.e.event : p.type === 'kanda' ? p.k.kanda : p.type === 'path' ? 'The Path of Rama'
      : p.type === 'cast' ? 'Who\u2019s who' : p.type === 'end' ? 'The End' : 'Cover';
  }

  // ---- resume reading (per-viewer convenience; storage may be unavailable, so always guarded)
  var STORE_KEY = 'ramayana-storybook-illustrated:page';
  function saveSpot() { try { localStorage.setItem(STORE_KEY, pageId(pages[at])); } catch (e) { /* ignore */ } }
  function savedSpot() {
    try {
      var id = localStorage.getItem(STORE_KEY);
      var i = id ? pageIndex(function (q) { return pageId(q) === id; }) : 0;
      return i > 0 && pageId(pages[i]) === id ? i : 0;
    } catch (e) { return 0; }
  }

  // ------------------------------------------------------------- helpers
  function deva(n) { return String(n).split('').map(function (d) { return DEVA_DIGITS.charAt(+d) || d; }).join(''); }
  function shortDeva(k) { return String(k.kandadevanagari).replace('काण्ड', ''); }
  function listSentence(a) { return a.length < 2 ? a.join('') : a.slice(0, -1).join(', ') + ' and ' + a[a.length - 1]; }
  function who(e) { return (DB.cast[e.eventid] || []).filter(function (x) { return x.c; }).map(function (x) { return x.c.character; }); }
  function pageIndex(pred) { for (var i = 0; i < pages.length; i++) { if (pred(pages[i])) { return i; } } return 0; }

  function go(i) {
    stopTrace();
    at = Math.max(0, Math.min(pages.length - 1, i));
    render();
  }

  // ------------------------------------------------------------- LEFT: art panel
  function art(slot, fallbackSlot, tint, deva, caption) {
    var src = IMAGES[slot] || (fallbackSlot && IMAGES[fallbackSlot]);
    if (src) {
      return h('figure', { cls: 'art' }, h('img', { src: src, alt: caption || '' }), caption ? h('figcaption', { text: caption }) : null);
    }
    // Typographic plate until the illustration exists.
    return h('figure', { cls: 'art art-plate', style: '--tint:' + tint },
      h('div', { cls: 'plate-frame' },
        h('span', { cls: 'plate-orn', 'aria-hidden': 'true', text: '॥ श्री राम ॥' }),
        h('span', { cls: 'plate-deva', lang: 'sa', text: deva }),
        caption ? h('span', { cls: 'plate-cap', text: caption }) : null));
  }

  function project(lat, lon) {
    return [(lon - GEO.bbox[0]) * GEO.cos * GEO.k, (GEO.bbox[3] - lat) * GEO.k];
  }

  function mapPanel() {
    var stops = DB.journey.map(function (j, i) {
      var l = DB.l[j.locationid];
      return { i: i, j: j, l: l, xy: l && has(l.maplatitude) ? project(num(l.maplatitude), num(l.maplongitude)) : null };
    }).filter(function (p) { return p.xy; });
    var upto = traced === null ? stops.length : traced;
    var svg = s('svg', { viewBox: '-10 -10 ' + (GEO.width + 20) + ' ' + (GEO.height + 20), cls: 'map', role: 'img', 'aria-label': 'Map of the places traditionally associated with Rama’s journey' },
      s('rect', { x: 0, y: 0, width: GEO.width, height: GEO.height, cls: 'sea' }),
      s('path', { d: GEO.path, cls: 'land' }),
      s('text', { x: GEO.width * 0.12, y: GEO.height * 0.62, cls: 'sea-label' }, 'Arabian Sea'),
      s('text', { x: GEO.width * 0.70, y: GEO.height * 0.60, cls: 'sea-label' }, 'Bay of Bengal'),
      s('rect', { x: 0, y: 0, width: GEO.width, height: GEO.height, cls: 'frame' }));
    stops.forEach(function (p, n) {
      if (!n) { return; }
      var q = stops[n - 1];
      var isReturn = n === stops.length - 1 && p.j.locationid === stops[0].j.locationid;
      svg.appendChild(s('line', { x1: q.xy[0], y1: q.xy[1], x2: p.xy[0], y2: p.xy[1],
        cls: 'leg' + (isReturn ? ' leg-return' : '') + (n < upto ? '' : ' leg-ahead') }));
    });
    var drawn = {};
    stops.forEach(function (p, n) {
      var on = activeStop === p.i;
      var reached = n < upto;
      var first = !drawn[p.j.locationid];
      drawn[p.j.locationid] = true;
      var side = MAP_LABELS[p.j.locationid];
      var showLabel = on || (side && first && reached);
      var dx = side === 'left' ? -9 : 9;
      svg.appendChild(s('g', { cls: 'stop' + (on ? ' on' : '') + (reached ? '' : ' ahead') },
        s('circle', { cx: p.xy[0], cy: p.xy[1], r: on ? 7 : 4 }),
        showLabel ? s('text', { x: p.xy[0] + (on && !side ? 10 : dx), y: p.xy[1] + 4, 'text-anchor': (side === 'left' && !on) || (on && side === 'left') ? 'end' : 'start' }, p.l.location) : null));
    });
    return h('figure', { cls: 'art art-map' }, svg,
      h('figcaption', { text: 'Traditional associations, placed approximately. Not a claim of historical geography.' }));
  }

  // ------------------------------------------------------------- RIGHT: story pages
  function coverText() {
    return h('div', { cls: 'text text-cover' },
      h('p', { cls: 'kicker', lang: 'sa', text: 'वाल्मीकि रामायण' }),
      h('h1', { cls: 'cover-title', lang: 'sa', text: 'रामायण' }),
      h('p', { cls: 'cover-sub', text: 'The Ramayana' }),
      h('p', { cls: 'lede', text: 'The journey of Rama, from Ayodhya to Lanka and home again, told in seven Kandas.' }),
      h('ol', { cls: 'toc' }, DB.kandas.map(function (k, i) {
        return h('li', null, h('button', { onclick: function () { go(pageIndex(function (p) { return p.type === 'kanda' && p.ki === i; })); } },
          h('span', { cls: 'toc-n', lang: 'sa', text: deva(i + 1) }),
          h('span', { cls: 'toc-d', lang: 'sa', text: k.kandadevanagari }),
          h('span', { cls: 'toc-e', text: k.kanda })));
      })),
      h('button', { cls: 'begin', onclick: function () { go(1); } }, 'Begin the story'),
      (function () {
        var i = savedSpot();
        return i > 1 ? h('p', { cls: 'resume' }, h('button', { cls: 'linkish', onclick: function () { go(i); } },
          'Continue reading: ' + pageLabel(pages[i]) + ' \u2192')) : null;
      })());
  }

  function pathText() {
    var stop = activeStop === null ? null : DB.journey[activeStop];
    var loc = stop && DB.l[stop.locationid];
    return h('div', { cls: 'text' },
      h('p', { cls: 'count', text: 'Before the story' }),
      h('h1', { cls: 'deva-title', lang: 'sa', text: 'राम वन गमन पथ' }),
      h('h2', { cls: 'en-title', text: 'The Path of Rama' }),
      h('p', { cls: 'body', text: 'From Ayodhya through the forests of central India, south to Kishkindha and the sea, across to Lanka, and home again.' }),
      h('ol', { cls: 'stops' }, DB.journey.map(function (j, i) {
        var k = DB.kandas.filter(function (x) { return x.kandaid === j.kandaid; })[0];
        return h('li', null, h('button', { cls: activeStop === i ? 'on' : '', onclick: function () { stopTrace(); activeStop = activeStop === i ? null : i; render(); } },
          h('span', { cls: 'stop-n', text: String(i + 1) }),
          h('span', { cls: 'stop-name', text: (DB.l[j.locationid] || {}).location }),
          h('span', { cls: 'stop-k', lang: 'sa', text: k ? shortDeva(k) : '' })));
      })),
      h('p', { cls: 'stop-detail', 'aria-live': 'polite' }, stop ? [h('strong', { text: loc.location + ': ' }), stop.storymilestone + '. ', h('em', { text: loc.modernassociation + '.' })] : 'Select a stop, or trace the whole journey.'),
      h('button', { cls: 'trace', onclick: trace }, timer ? '■ Stop' : '▶ Trace the journey'));
  }

  function kandaText(p) {
    var k = p.k;
    var newcomers = DB.firstIn[k.kandaid] || [];
    return h('div', { cls: 'text' },
      h('p', { cls: 'count', text: 'Kanda ' + (p.ki + 1) + ' of ' + DB.kandas.length }),
      h('h1', { cls: 'deva-title', lang: 'sa', text: k.kandadevanagari }),
      h('h2', { cls: 'en-title', text: k.kanda }),
      h('p', { cls: 'gloss', text: k.englishgloss }),
      h('p', { cls: 'body dropcap', text: k.storyintro }),
      k.scopenote ? h('p', { cls: 'note', text: k.scopenote }) : null,
      h('ol', { cls: 'episodes' }, p.evs.map(function (e) {
        var key = e.keymoment === 'Y';
        return h('li', { cls: key ? 'key' : '' }, key
          ? h('button', { onclick: function () { go(pageIndex(function (q) { return q.type === 'moment' && q.e === e; })); } }, e.event)
          : h('span', { text: e.event }));
      })),
      newcomers.length ? h('p', { cls: 'note' }, h('span', { cls: 'label', text: 'Entering the story ' }), listSentence(newcomers) + '.') : null);
  }

  function momentText(p) {
    var e = p.e, k = p.k;
    var loc = DB.l[e.locationid];
    var cast = who(e);
    return h('div', { cls: 'text' },
      h('p', { cls: 'count' }, h('span', { lang: 'sa', text: k.kandadevanagari }), ' · ' + k.kanda + ' · ' + p.n + ' of ' + p.of),
      h('h1', { cls: 'moment-title', text: e.event }),
      h('p', { cls: 'body dropcap', text: e.narrative || e.summary }),
      h('p', { cls: 'meta' }, loc ? h('span', { cls: 'place', text: loc.location }) : null, loc && cast.length ? '  ·  ' : '', cast.length ? 'with ' + listSentence(cast) : ''),
      String(e.confidencelabel).indexOf('Interpretive') === 0 ? h('p', { cls: 'note', text: e.chronologynote + '.' }) : null);
  }

  // ------------------------------------------------------------- mini map inset (Kanda / moment pages)
  function kandaPlaces(kid) {
    var ids = [];
    DB.journey.forEach(function (j) { if (j.kandaid === kid && ids.indexOf(j.locationid) < 0) { ids.push(j.locationid); } });
    DB.events.forEach(function (e) { if (e.kandaid === kid && e.locationid && ids.indexOf(e.locationid) < 0) { ids.push(e.locationid); } });
    return ids.filter(function (id) { return DB.l[id] && has(DB.l[id].maplatitude); });
  }

  function miniMap(p) {
    var ids = p.type === 'moment' ? (p.e.locationid && DB.l[p.e.locationid] && has(DB.l[p.e.locationid].maplatitude) ? [p.e.locationid] : []) : kandaPlaces(p.k.kandaid);
    if (!ids.length) { return null; }
    var route = DB.journey.map(function (j) { var l = DB.l[j.locationid]; return l && has(l.maplatitude) ? project(num(l.maplatitude), num(l.maplongitude)) : null; })
      .filter(Boolean).map(function (xy) { return xy[0].toFixed(1) + ',' + xy[1].toFixed(1); }).join(' ');
    var svg = s('svg', { viewBox: '0 0 ' + GEO.width + ' ' + GEO.height, role: 'img', 'aria-label': 'Where this happens' },
      s('path', { d: GEO.path, cls: 'mm-land' }),
      s('polyline', { points: route, cls: 'mm-route' }),
      ids.map(function (id) {
        var l = DB.l[id], xy = project(num(l.maplatitude), num(l.maplongitude));
        return s('g', { cls: 'mm-place' }, s('circle', { cx: xy[0], cy: xy[1], r: 9 }), s('title', null, l.location));
      }));
    var names = ids.map(function (id) { return DB.l[id].location; });
    return h('aside', { cls: 'minimap', onclick: function () { go(1); }, title: 'Open the Path of Rama' }, svg,
      h('p', { cls: 'mm-cap', text: p.type === 'moment' ? names[0] : (names.length > 3 ? names.slice(0, 3).join(', ') + '…' : names.join(', ')) }));
  }

  // ------------------------------------------------------------- Who's who
  var FACTION_ORDER = ['Ayodhya & Mithila', 'Kishkindha', 'Lanka', 'Sages & Forest'];
  // Main cast per world (editorial): Rama, Sita, Lakshmana, Bharata | Hanuman, Sugriva, Vali, Jambavan |
  // Ravana, Meghnad, Kumbhakarna, Vibhishana | Vishvamitra, Jatayu, Shabari, Guha.
  var FEATURED = ['C001', 'C002', 'C003', 'C004', 'C013', 'C014', 'C015', 'C016', 'C020', 'C024', 'C023', 'C022', 'C011', 'C027', 'C029', 'C037'];
  var FACTION_DEVA = { 'Ayodhya & Mithila': 'अयोध्या व मिथिला', 'Kishkindha': 'किष्किन्धा', 'Lanka': 'लङ्का', 'Sages & Forest': 'ऋषि व वन' };

  function castText(p) {
    var count = {};
    Object.keys(DB.cast).forEach(function (eid) { DB.cast[eid].forEach(function (x) { if (x.c) { count[x.c.characterid] = (count[x.c.characterid] || 0) + 1; } }); });
    var all = Object.keys(DB.c).map(function (id) { return DB.c[id]; });
    return h('div', { cls: 'text' },
      h('p', { cls: 'count', text: 'Before the story \u00B7 ' + (p.part + 1) + ' of 2' }),
      h('h1', { cls: 'deva-title', lang: 'sa', text: 'पात्र परिचय' }),
      h('h2', { cls: 'en-title', text: 'Who’s Who' }),
      h('div', { cls: 'cast' }, FACTION_ORDER.slice(p.part * 2, p.part * 2 + 2).map(function (f) {
        // Editorial main cast first (story importance), then fill any gap by episode count.
        var featured = FEATURED.map(function (id) { return DB.c[id]; }).filter(function (c) { return c && c.faction === f; });
        var rest = all.filter(function (c) { return c.faction === f && featured.indexOf(c) < 0; })
          .sort(function (a, b) { return (count[b.characterid] || 0) - (count[a.characterid] || 0) || String(a.character).localeCompare(String(b.character)); });
        var people = featured.concat(rest).slice(0, 4);
        return h('section', { cls: 'cast-group' },
          h('h3', null, h('span', { lang: 'sa', text: FACTION_DEVA[f] }), h('span', { cls: 'cast-en', text: f })),
          h('ul', null, people.map(function (c) {
            return h('li', null, h('strong', { text: c.character }), h('span', { text: c.description }));
          })));
      })),
      h('p', { cls: 'note', text: p.part === 0 ? 'Rama\u2019s world: the royal house and the Vanara allies. Lanka and the sages follow \u2192' : 'The rakshasa kingdom of Lanka, and the sages and forest dwellers who guide Rama.' }));
  }

  // ------------------------------------------------------------- closing page
  function endText() {
    var keys = DB.events.filter(function (e) { return e.keymoment === 'Y'; }).length;
    var live = !dataNote;
    return h('div', { cls: 'text text-end' },
      h('h1', { cls: 'deva-title', lang: 'sa', text: '॥ इति ॥' }),
      h('h2', { cls: 'en-title', text: 'The End' }),
      h('p', { cls: 'body', text: 'From a childless king’s prayer in Ayodhya to a coronation fourteen years after an exile, the Ramayana crosses the whole land: forest, mountain, ocean and island. It has been retold across centuries and languages, and each retelling returns to the question it keeps asking of Rama: what is the right thing to do?' }),
      h('div', { cls: 'about' },
        h('p', { cls: 'label', text: 'About this storybook' }),
        h('p', null, 'A Tableau data app. Its ' + DB.events.length + ' episodes, ' + Object.keys(DB.c).length + ' characters, ' + keys +
          ' key moments and ' + DB.journey.length + ' journey stops are ' + (live ? 'read live from the published data source ' : 'shown from a bundled copy of the data source ') +
          'Ramayana_Story_Data, which is built and tested by a Python data pipeline.'),
        h('p', null, 'Texts are short paraphrases of the Valmiki Ramayana, not translations. Places are traditional associations, placed approximately. Map outline: Natural Earth.')),
      h('div', { cls: 'end-actions' },
        h('button', { cls: 'begin', onclick: function () { go(0); } }, 'Read again'),
        h('button', { cls: 'linkish', onclick: function () { go(1); } }, 'The Path of Rama →')));
  }

  // ------------------------------------------------------------- bottom navigation
  function navBar() {
    var p = pages[at];
    var nK = DB.kandas.length;
    // segment order: cover(-3) path(-2) cast(-1) kandas(0..n-1) end(n)
    var cur = p.type === 'cover' ? -3 : p.type === 'path' ? -2 : p.type === 'cast' ? -1 : p.type === 'end' ? nK : p.ki;
    var segs = [['Cover', -3, 0], ['\u092A\u0925', -2, 1], ['\u092A\u093E\u0924\u094D\u0930', -1, 2]].concat(DB.kandas.map(function (k, i) {
      return [shortDeva(k), i, pageIndex(function (q) { return q.type === 'kanda' && q.ki === i; })];
    }), [['\u0907\u0924\u093F', nK, pages.length - 1]]);
    var sub = null;
    if (p.type === 'kanda' || p.type === 'moment') {
      var kp = pageIndex(function (q) { return q.type === 'kanda' && q.ki === p.ki; });
      sub = h('span', { cls: 'subdots', 'aria-hidden': 'true' }, [kp].concat(p.type === 'kanda' ? p.keys.map(function (_, j) { return kp + j + 1; }) : pages.reduce(function (a, q, idx) { if (q.type === 'moment' && q.ki === p.ki) { a.push(idx); } return a; }, [])).map(function (idx) {
        return h('i', { cls: idx === at ? 'on' : '' });
      }));
    }
    return h('nav', { cls: 'nav', 'aria-label': 'Story navigation' },
      h('button', { cls: 'arrow', 'aria-label': 'Previous page', disabled: at === 0 ? 'disabled' : null, onclick: function () { go(at - 1); } }, '←'),
      h('ol', { cls: 'segs' }, segs.map(function (sg) {
        return h('li', null, h('button', { cls: (sg[1] === cur ? 'on' : '') + (sg[1] < cur ? ' done' : ''), lang: sg[1] > -3 ? 'sa' : null,
          'aria-current': sg[1] === cur ? 'step' : null, onclick: function () { go(sg[2]); } }, sg[0]));
      })),
      sub,
      h('button', { cls: 'arrow', 'aria-label': 'Next page', disabled: at === pages.length - 1 ? 'disabled' : null, onclick: function () { go(at + 1); } }, '→'));
  }

  // ------------------------------------------------------------- journey trace animation
  function stopTrace() { if (timer) { clearInterval(timer); timer = null; } traced = null; }
  function trace() {
    if (timer) { stopTrace(); render(); return; }
    traced = 1; activeStop = 0; render();
    timer = setInterval(function () {
      if (traced >= DB.journey.length) { clearInterval(timer); timer = null; traced = null; render(); return; }
      traced += 1; activeStop = traced - 1; render();
    }, 900);
  }

  // ------------------------------------------------------------- render
  function render() {
    try {
      var p = pages[at];
      var left, right, tint = '#6e1f17';
      if (p.type === 'cover') { left = art('cover', null, '#5a2416', 'रामायण', null); right = coverText(); }
      else if (p.type === 'path') { left = mapPanel(); right = pathText(); }
      else if (p.type === 'cast') { left = art('cast', null, '#3a2a1a', '\u092A\u093E\u0924\u094D\u0930 \u092A\u0930\u093F\u091A\u092F', 'Who\u2019s who \u00B7 ' + (p.part + 1) + ' of 2'); right = castText(p); }
      else if (p.type === 'end') { left = art('end', 'cover', '#4a1a12', '\u0965 \u0907\u0924\u093F \u0965', 'The End'); right = endText(); }
      else {
        tint = TINTS[p.ki % TINTS.length];
        left = p.type === 'kanda'
          ? art(p.k.kandaid, null, tint, p.k.kandadevanagari, p.k.kanda)
          : art(p.e.eventid, p.k.kandaid, tint, p.k.kandadevanagari, p.e.event);
        right = p.type === 'kanda' ? kandaText(p) : momentText(p);
      }
      root.textContent = '';
      root.appendChild(h('div', { cls: 'book page-' + p.type, style: '--tint:' + tint },
        h('div', { cls: 'left' }, left),
        h('div', { cls: 'right' }, (p.type === 'kanda' || p.type === 'moment') ? miniMap(p) : null, h('div', { cls: 'scroll' }, right), navBar(), dataNote ? h('p', { cls: 'data-note', text: dataNote }) : null)));
      fit();
      saveSpot();
    } catch (err) {
      renderError((err && err.message) || String(err));
    }
  }

  // Fit the page to the frame (Tableau's view can be ~540px tall): shrink the text block in small
  // steps until nothing scrolls. Floor at 62% so text stays readable; phones stack and may scroll.
  var MIN_ZOOM = 0.62;
  function fit() {
    var box = document.querySelector('.scroll'), text = box && box.firstChild;
    if (!text || window.innerWidth <= 760) { if (text) { text.style.zoom = ''; } return; }
    var z = 1;
    text.style.zoom = '';
    while (box.scrollHeight > box.clientHeight + 1 && z > MIN_ZOOM) {
      z = Math.round((z - 0.04) * 100) / 100;
      text.style.zoom = String(z);
    }
  }
  var resizeTimer = null;
  window.addEventListener('resize', function () { clearTimeout(resizeTimer); resizeTimer = setTimeout(fit, 120); });

  document.addEventListener('keydown', function (e) {
    if (!DB) { return; }
    if (e.key === 'ArrowRight') { go(at + 1); }
    if (e.key === 'ArrowLeft') { go(at - 1); }
  });

  function setStatus(msg) {
    var el = document.querySelector('.loading-status');
    if (el) { el.textContent = msg; }
  }

  function boot() {
    if (!root) { return; }
    root.appendChild(h('p', { cls: 'loading', lang: 'sa', text: 'रामायण' }));
    root.appendChild(h('p', { cls: 'loading-status', text: 'Opening the book…' }));
    // Standalone web edition (GitHub Pages): no Tableau, read the bundled snapshot directly.
    if (!window.tableau || !tableau.extensions) {
      if (!GEO || !window.RAMAYANA_DATA) { renderError('Story data not loaded'); return; }
      DB = model(JSON.parse(JSON.stringify(window.RAMAYANA_DATA))); buildPages(); render(); return;
    }
    if (!GEO) { renderError('Map data (geo.js) not loaded'); return; }
    // Live first (published data source); if that fails, fall back to the bundled snapshot so the
    // story still opens, and say so quietly at the bottom of the page.
    function source() {
      return load().catch(function (err) {
        if (!window.RAMAYANA_DATA) { throw err; }
        dataNote = 'Showing the bundled copy of the story; live data unavailable: ' + String((err && err.message) || err).slice(0, 160);
        return model(JSON.parse(JSON.stringify(window.RAMAYANA_DATA)));
      });
    }
    tableau.extensions.initializeAsync().then(source).then(function (db) { DB = db; buildPages(); render(); })
      .catch(function (err) { renderError((err && (err.message || err.errorCode)) || String(err)); });
  }

  boot();
})();
